#!/usr/bin/env python3
"""Write coverage.md (coverage + overlap report) from the generated tables."""
import json, csv, collections, pickle
H=lambda x:'0x%x'%x
cov=json.load(open('coverage.json')); rec=json.load(open('reconcile.json')); summ=json.load(open('summary.json'))
F=pickle.load(open('F.pkl','rb'))
ov=list(csv.DictReader(open('overlaps.tsv'),delimiter='\t'))
gaps=list(csv.DictReader(open('gaps.tsv'),delimiter='\t'))
L=[]
w=L.append
w('# Coverage and overlap report\n')
w('Generated by `u8_report.py` from `coverage.json`, `gaps.tsv`, `overlaps.tsv`. All numbers are byte or object counts.\n')
w('## Executable bytes\n')
w('Executable sections: `.text` (RVA 0x1000-0x5783f3) and `.nep` (RVA 0x579000-0x57a276; CLR native-entry stub section). Total %d bytes.\n'%cov['total_exec_bytes'])
w('| class | bytes | share of executable bytes |\n|---|---:|---:|')
w('| inside a function extent (all kinds) | %d | %.4f%% |'%(cov['function_bytes'],100*cov['function_fraction']))
for k,v in sorted(cov['non_function_classes'].items(),key=lambda kv:-kv[1]['bytes']):
    w('| %s | %d | %.4f%% |'%(k,v['bytes'],100*v['fraction']))
w('| unknown / unclassified | %d | 0.0000%% |'%sum(int(g['size']) for g in gaps if g['class']=='unknown'))
w('\nAccounted fraction: %.6f (function extents + classified non-function bytes = all executable bytes).\n'%cov['accounted_fraction'])
w('| section | bytes | .pdata function bytes | leaf (no .pdata) function bytes | function fraction |\n|---|---:|---:|---:|---:|')
for s,v in cov['by_section'].items():
    w('| %s | %d | %d | %d | %.4f%% |'%(s,v['bytes'],v['pdata_function_bytes'],v['leaf_function_bytes'],100*v['function_fraction']))
w('\n`.pdata` alone covers %.2f%% of `.text` (the 85%% quoted by the spikes). The leaf (no `.pdata`) functions found here add %.2f%% of `.text`, IL bodies and padding make up the rest.\n'%(100*cov['pdata_only_fraction_of_text'],100*cov['by_section']['.text']['leaf_function_bytes']/cov['by_section']['.text']['bytes']))
w('## What the non-function bytes are\n')
w('| class | runs | bytes | meaning |\n|---|---:|---:|---|')
meaning={'padding-int3':'`0xCC` runs between functions (all bytes verified to be 0xCC)','padding-nop':'multi-byte NOP padding that is not part of any reached function','il-align-pad':'zero bytes (at most 3) that align a CLR IL method body to 4 bytes','clr-il-body':'CLR IL method bodies stored inside `.text` (mixed-mode image); extents derived from the IL method headers (tiny/fat header, code size, extra sections); data, not x64 code'}
for k,v in sorted(cov['non_function_classes'].items(),key=lambda kv:-kv[1]['bytes']):
    w('| %s | %d | %d | %s |'%(k,v['runs'],v['bytes'],meaning.get(k,'')))
w('\nData that sits INSIDE function extents (not counted above, listed in `functions.json` `data_in_code`): %d bytes of MSVC jump tables / byte-index tables / two unclassified data chunks; %d bytes of trailing `0xCC` inside `.pdata` ranges.\n'%(cov['jump_table_bytes_inside_function_ranges'],cov['trailing_int3_inside_pdata_ranges']))
w('`gaps.tsv` lists every non-function run (%d rows) with its class.\n'%len(gaps))
w('## Overlap report\n')
w('- Overlaps between any two function ranges or between a range and a CLR IL body: **%d** (`overlaps.tsv` has only its header).'%len(ov))
w('- Ranges checked: %d, belonging to %d functions.'%(sum(len(f['ranges']) for f in F),len(F)))
w('- No leaf (no `.pdata`) range touches a `.pdata` range; no two leaf functions share an instruction or a jump table (checked at instruction level during discovery and again by `validate.py`).')
w('- Distinct direct call / jmp targets recorded: every one is a function start (%d targets, 0 into the interior of another function, 0 into padding or data).'%len(set(t for f in F for t in f["calls"]+f["tails"])))
w('- Every one of the 27,139 base-relocated code pointers and all 20,667 vtable slots point at a function start.')
w('- The only code address taken from inside the image that is not a function start is one `lea` of a catch-continuation label inside the same function (an interior label, not a function).')
w('\nTail-merged code (several small entry stubs that all `jmp` to one shared body, e.g. 0x4efe10 / 0x4efe30 -> 0x4efe50) is split into one function per stub plus one function for the shared body: during discovery a jump to a 16-byte-aligned address that follows `int3` padding, or to an address below the function entry, is treated as a tail call, never as an internal branch. This is what keeps the extents disjoint.\n')
w('## Reconciliation with the 30,246 estimate\n')
w('The spikes counted 17,908 `.pdata` roots + 12,338 leaf functions = 30,246. This table has **%d** functions: 17,908 merged `.pdata` functions + %d leaf functions.\n'%(summ['n_functions'],rec['ours_leaf_no_pdata']))
w('| item | count |\n|---|---:|')
w('| S7 leaf functions confirmed here | %d |'%rec['s7_leaf_found_in_ours'])
w('| S7 leaf entries not functions here (3 are interior addresses of one leaf, 1 lies in padding) | %d |'%rec['s7_leaf_missing_in_ours'])
w('| added: cleanup funclets with no `.pdata` (EH UnwindMap actions) | %d |'%rec['ours_only_funclets'])
for k,v in sorted(rec['ours_only_by_primary_source'].items(),key=lambda kv:-kv[1]):
    if k!='eh-cleanup': w('| added: primary source `%s` | %d |'%(k,v))
w('| added in total | %d |'%rec['ours_only_total'])
w('\nOf the added functions, %d have no reference of any kind (confidence `low`, flag `unreferenced`): leaf code that nothing in the image calls, jumps to, points at or registers. They are real decodable functions (decode cleanly to a `ret`/`jmp`; almost all 16-byte aligned after `int3` padding, the exceptions carry the flag `unaligned16`) but are probably dead code; keep them in the universe so the lifted image is complete, and prune later if wanted.\n'%rec['ours_only_unreferenced'])
open('coverage.md','w').write('\n'.join(L)+'\n')
print('\n'.join(L)[:1500])
